S=/tmp/claude-0/-tmp-eff-1igff2by-work/0536cbf5-c97a-5467-80bd-e50c5d30a2ce/scratchpad; python3 -I - "$S/dash.json" "$S/dash2.json" <<'EOF'
import json,sys
d=json.load(open(sys.argv[1]))
for p in d["panels"]:
    c=p["config"]
    if c["type"]=="xy":
        c.pop("axis",None)
        for l in c["layers"]:
            if l["type"]=="bar":
                l["y"]=[{"column":"count"}]
json.dump(d,open(sys.argv[2],"w"),indent=1)
EOF
curl -sS -X POST -H "kbn-xsrf: true" -H "Authorization: ApiKey $KIBANA_TEST_API_KEY" -H "Content-Type: application/json" "$KIBANA_URL/api/dashboards" -d @$S/dash2.json | head -c 1200

